1	package org.springframework.samples.petclinic.rest.controller.v2;
2	
3	import org.springframework.data.domain.Page;
4	import org.springframework.data.domain.PageRequest;
5	import org.springframework.data.domain.Sort;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.api.OwnerV2Api;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	import org.springframework.security.access.prepost.PreAuthorize;
14	import org.springframework.web.bind.annotation.CrossOrigin;
15	import org.springframework.web.bind.annotation.RestController;
